package it.frociart.app;

/** Metadata for native source actions; the app never executes generated programs. */
final class FlowSourceTarget {
    static final FlowSourceTarget PYTHON=new FlowSourceTarget("python","Python","py","PythonRuntime.py","Salva il programma completo ed eseguilo con Python 3 sul computer.");
    static final FlowSourceTarget JAVA=new FlowSourceTarget("java","Java","java","JavaRuntime.txt","Salva Programma.java, compila con javac ed esegui con java Programma (Java 8+).");
    static final FlowSourceTarget KOTLIN=new FlowSourceTarget("kotlin","Kotlin","kt","KotlinRuntime.kt","Salva Programma.kt. Compila con Kotlin/JVM 1.9+: kotlinc Programma.kt -include-runtime -d Programma.jar. Esegui: java -jar Programma.jar (Java 8+). Il file contiene il programma completo; i disegni si aprono in una finestra. File e bozze usano la cartella di esecuzione.");
    static final FlowSourceTarget CSHARP=new FlowSourceTarget("csharp","C#","cs","CSharpRuntime.txt","Salva Programma.cs. Su Windows: csc /r:System.Numerics.dll Programma.cs. I disegni vengono salvati in SVG.");
    static final FlowSourceTarget JAVASCRIPT=new FlowSourceTarget("javascript","JavaScript","cjs","JavaScriptRuntime.cjs","Salva Programma.cjs ed esegui con node Programma.cjs (Node.js 22+). I disegni vengono salvati in SVG.");
    static final FlowSourceTarget TYPESCRIPT=new FlowSourceTarget("typescript","TypeScript","cts","TypeScriptRuntime.cts","Salva Programma.cts. Compila: tsc --strict --target ES2020 --module node16 Programma.cts. Esegui: node Programma.cjs (Node.js 22+).");
    static final FlowSourceTarget CPP=new FlowSourceTarget("cpp","C++","cpp","CppRuntime.txt","Salva Programma.cpp. Compila con g++ -std=c++17 -O2 Programma.cpp -o Programma; avvia Programma. Su Linux/macOS aggiungi -pthread. File e SVG usano la cartella di esecuzione; prima di sostituire un file viene chiesta conferma. Le scritture interrotte restano in una bozza nella destinazione.");
    static final FlowSourceTarget VISUALBASIC=new FlowSourceTarget("vbnet","Visual Basic .NET","vb","VisualBasicRuntime.txt","Salva Programma.vb. Con un compilatore Visual Basic .NET disponibile usa: vbc /r:System.Numerics.dll Programma.vb. Il file contiene il programma completo; file e disegni SVG usano la cartella di esecuzione.");
    static final FlowSourceTarget GROOVY=new FlowSourceTarget("groovy","Groovy","groovy","JavaRuntime.txt","Salva Programma.groovy ed esegui con groovy Programma.groovy (Groovy 5+, Java 17+). Il file contiene il programma completo. File e bozze usano la cartella di esecuzione; i disegni si aprono in una finestra.");
    static final FlowSourceTarget RUBY=new FlowSourceTarget("ruby","Ruby","rb","RubyRuntime.rb","Salva Programma.rb ed esegui ruby Programma.rb (Ruby 3.3+). Non servono Frociart o gem aggiuntive. File e bozze usano la cartella di esecuzione; prima di sostituire un file viene chiesta conferma. Il disegno viene salvato in Frociart_disegno.svg. Su Windows il salvataggio usa Fiddle, incluso nelle installazioni complete di Ruby.");
    static final FlowSourceTarget POWERSHELL=new FlowSourceTarget("powershell","PowerShell","ps1","CSharpRuntime.txt","Salva Programma.ps1 in UTF-8 con BOM. Su Windows usa powershell -File Programma.ps1; con PowerShell 7+ usa pwsh -File Programma.ps1. Add-Type prepara il supporto .NET locale: la prima esecuzione può richiedere qualche secondo. Non servono Frociart o moduli esterni. File, bozze e disegni SVG usano la cartella di esecuzione.");
    static final FlowSourceTarget PHP=new FlowSourceTarget("php","PHP","php","PhpRuntime.php","Salva Programma.php ed esegui php Programma.php sul computer (PHP 8.2+, CLI a 64 bit). Non servono Frociart o estensioni aggiuntive. File e bozze usano la cartella di esecuzione; prima di sostituire un file viene chiesta conferma. Il disegno viene salvato in Frociart_disegno.svg.");
    static final FlowSourceTarget[] ALL={PYTHON,JAVA,KOTLIN,CSHARP,CPP,JAVASCRIPT,TYPESCRIPT,VISUALBASIC,GROOVY,RUBY,POWERSHELL,PHP};
    final String id,name,extension,runtime,instructions;
    final FlowCodeTemplate template;final String templateId;
    private FlowSourceTarget(String id,String name,String extension,String runtime,String instructions){this(id,name,extension,runtime,instructions,null,null);}
    private FlowSourceTarget(String id,String name,String extension,String runtime,String instructions,FlowCodeTemplate template,String templateId){this.id=id;this.name=name;this.extension=extension;this.runtime=runtime;this.instructions=instructions;this.template=template;this.templateId=templateId;}
    static FlowSourceTarget fromTemplate(String id,FlowCodeTemplate definition){if(definition==null||id==null||!id.matches("[a-f0-9]{32}"))throw new IllegalArgumentException("Identificativo del modello non valido.");FlowSourceTarget basis=find(definition.base);String instructions=!definition.instructions.isEmpty()?definition.instructions:basis==null?"Il formato è definito dal modello. Controlla il testo prima di usarlo nel programma di destinazione.":basis.instructions;return new FlowSourceTarget("template:"+id,definition.name,definition.extension,basis==null?null:basis.runtime,instructions,definition,id);}
    FlowSourceText generate(FlowSource.Program program,String runtime){if(template!=null){FlowSourceTarget basis=find(template.base);return template.generate(program,basis==null?null:basis.generate(program,runtime));}if(this==PYTHON)return FlowPython.generate(program,runtime);if(this==JAVA)return FlowJava.generate(program,runtime);if(this==PHP)return FlowPhp.generate(program,runtime);if(this==POWERSHELL)return FlowPowerShell.generate(program,runtime);if(this==RUBY)return FlowRuby.generate(program,runtime);if(this==GROOVY)return FlowGroovy.generate(program,runtime);if(this==KOTLIN)return FlowKotlin.generate(program,runtime);if(this==CSHARP)return FlowCSharp.generate(program,runtime);if(this==CPP)return FlowCpp.generate(program,runtime);if(this==VISUALBASIC)return FlowVisualBasic.generate(program,runtime);if(this==JAVASCRIPT||this==TYPESCRIPT)return FlowJavaScript.generate(program,runtime,this==TYPESCRIPT);throw new IllegalStateException("Linguaggio non disponibile.");}
    FlowSourceText generateTyped(FlowSource.Program program,String runtime,java.util.Map<String,Integer> choices){return template!=null&&template.fpgt!=null?template.generateTyped(program,null,choices):generate(program,runtime);}
    String fileName(String source){if(template!=null&&template.fpgt!=null&&extension.equalsIgnoreCase("java")&&source!=null){java.util.regex.Matcher match=java.util.regex.Pattern.compile("(?m)^[ \\t]*public[ \\t]+(?:(?:final|abstract)[ \\t]+)?class[ \\t]+([A-Za-z_$][A-Za-z0-9_$]{0,127})\\b").matcher(source);if(match.find()&&!match.group(1).matches("(?i)(?:CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])"))return match.group(1)+".java";}return "Programma."+extension;}
    static FlowSourceTarget find(String id){for(FlowSourceTarget target:ALL)if(target.id.equals(id))return target;return null;}
    static String nameOf(String id){FlowSourceTarget target=find(id);return id.equals("flowgorithm")?"Flowgorithm · .fpgt":target==null?id:target.name;}
    static String supportMarker(String id){return id.equals("vbnet")?"    ' --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---":id.equals("python")||id.equals("ruby")||id.equals("powershell")?"# --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---":id.equals("java")||id.equals("kotlin")||id.equals("csharp")||id.equals("groovy")?"    // --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---":id.equals("cpp")||id.equals("javascript")||id.equals("typescript")||id.equals("php")?"// --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---":null;}
}
